#include "grade_school.h"

#include <map>
#include <string>
#include <vector>
#ifdef EXERCISM_TEST_SUITE
#include <catch2/catch.hpp>
#else
#include "test/catch.hpp"
#endif

using namespace std;

TEST_CASE("roster_is_empty_when_no_student_is_added",
          "[a3f0fb58-f240-4723-8ddc-e644666b85cc]") {
    const grade_school::school school{};

    REQUIRE(school.roster().empty());
}

#if defined(EXERCISM_RUN_ALL_TESTS)
TEST_CASE("student_is_added_to_the_roster", "[6d0a30e4-1b4e-472e-8e20-c41702125667]") {
    grade_school::school school;
    school.add("Aimee", 2);

    const map<int, vector<string>> expected{{2, {"Aimee"}}};
    REQUIRE(expected == school.roster());
}

TEST_CASE("multiple_students_in_the_same_grade_are_added_to_the_roster",
          "[233be705-dd58-4968-889d-fb3c7954c9cc]") {
    grade_school::school school;
    school.add("Blair", 2);
    school.add("James", 2);
    school.add("Paul", 2);

    const map<int, vector<string>> expected{{2, {"Blair", "James", "Paul"}}};
    REQUIRE(expected == school.roster());
}

